task.vi:
Chỉ ra sự khác biệt giữa hai mảng sau đây:
char s1[] = {'a', 'b', 'c'};
char s2[] = "abc";

task.en:
What are the differences between the following arrays?
char s1[] = {'a', 'b', 'c'};
char s2[] = "abc";

example.code:
#include <iostream>
#include <cstring>

int main() {
    char city[30];
    // Read a full line including whitespace up to 29 chars + '\0'
    if (std::cin.getline(city, 30)) {
        std::cout << "City: " << city << "\n";
        std::cout << "Length: " << std::strlen(city) << "\n";
        std::cout << "Array capacity: " << sizeof(city) << "\n";
    }
    return 0;
}

#include <iostream>
#include <cstring>

int main() {
    char s1[20] = "Good ";
    char s2[] = "morning";

    // Concatenation
    std::strcat(s1, s2);
    std::cout << "Concatenated: " << s1 << "\n";

    // Comparison
    char s3[] = "Good afternoon";
    int cmp = std::strcmp(s1, s3);
    if (cmp > 0) {
        std::cout << "s1 is greater than s3\n";
    } else if (cmp == 0) {
        std::cout << "s1 is equal to s3\n";
    } else {
        std::cout << "s1 is less than s3\n";
    }

    // Prefix comparison
    if (std::strncmp(s1, s3, 4) == 0) {
        std::cout << "First 4 characters match ('Good')\n";
    }
    return 0;
}

