example.code:
#include <iostream>
#include <cstdlib>

int main() {
    char s1[] = "65";
    char s2[] = "4";
    char s3[] = "65.5";
    char s4[] = "4.4";

    // Integer conversion with atoi
    int intSum = std::atoi(s1) + std::atoi(s2);
    std::cout << "Integer sum: " << intSum << "\n";

    // Floating-point conversion with atof
    double floatSum = std::atof(s3) + std::atof(s4);
    std::cout << "Floating sum: " << floatSum << "\n";

    return 0;
}
